 * 같은 키가 다시 전달되면(재처리·재기동) 두 번 보내지 않는다.
 */
export class AlertConsumer {
  private nextOffset = 0;
  private readonly handledKeys = new Set<string>();

  constructor(
    private readonly client: MqpubClient,
    private readonly topic: string,
    private readonly customers: CustomerRepository,
    private readonly gateway: SmsGateway,
    private readonly log: DeliveryLogRepository,
    private readonly senderId: string,
    private readonly limit: number,
  ) {}

  position(): number {
    return this.nextOffset;
  }

  drain(runId: number): DrainResult {
    const rows = this.client.consume(this.topic, this.nextOffset).slice(0, this.limit);
    const result: DrainResult = { read: rows.length, delivered: [], failed: [] };
    for (const row of rows) {
      this.nextOffset = row.offset + 1;
      if (this.handledKeys.has(row.key)) continue;
      this.handledKeys.add(row.key);

      const n = decodePayload(row.payload);
      if (!n) {
        result.failed.push({ orderNo: "?", kind: "PAID", reason: "bad-payload" });
        continue;
      }
      const customer = this.customers.find(n.customerId);
      if (!customer) {
        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: "unknown-customer" });
        continue;
      }
      const receipt = this.gateway.send(this.senderId, customer.phone, renderAlert(n.kind, customer.name, n.orderNo));
      if (!receipt.ok) {
        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: receipt.reason ?? "sms-failed" });
        continue;
      }
      const d: DeliveredAlert = {
        runId,
        orderNo: n.orderNo,
        customerId: n.customerId,
        kind: n.kind,
        phone: customer.phone,
        receiptId: receipt.receiptId ?? "",
      };
      this.log.append(d);
      result.delivered.push(d);
    }
    return result;
  }
}
--- payloadCodec ---
import { Notification } from "../domain/notification";
import { isEventKind } from "../domain/order";

const VERSION = 2;
const MAX_PAYLOAD = 900;

interface WirePayload {
  v: number;
  o: string;
  c: string;
  k: string;
}

/** 탭·개행·제어문자는 와이어 형식(<key>TAB<payload>)을 깨므로 제거한다. */
function scrub(s: string): string {
  return s.replace(/[\u0000-\u001f\u007f]/g, "");
}

export function encodePayload(n: Notification): string {
  const body: WirePayload = { v: VERSION, o: scrub(n.orderNo), c: scrub(n.customerId), k: n.kind };
  const json = JSON.stringify(body);
  if (json.length > MAX_PAYLOAD) throw new Error("payload too large");
  return json;
}

export function decodePayload(raw: string): Notification | null {
  let body: Partial<WirePayload>;
  try {
    body = JSON.parse(raw) as Partial<WirePayload>;
  } catch {
    return null;
  }
  if (body.v !== VERSION && body.v !== 1) return null;
  if (typeof body.o !== "string" || typeof body.c !== "string" || !isEventKind(body.k)) return null;
  return { orderNo: body.o, customerId: body.c, kind: body.k };
}

